def find_first_occurrence(arr: list[int], target: int) -> int:
    low = 0
    high = len(arr) - 1
    result = -1

    while low <= high:
        mid = low + (high - low) // 2
        if arr[mid] == target:
            result = mid
            high = mid - 1  # Continue searching left
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    return result

